/**
 * Resource catalogue. Every entry gets the standard 8 endpoints
 * (list, count, search, get, create, replace, patch, delete) generated by
 * src/routes/resources.js and documented in the OpenAPI spec.
 *
 * Field spec:
 *   type      string | integer | number | boolean | date | datetime
 *   required  enforced on POST and PUT
 *   enum      allowed values
 *   ref       name of the resource the value must point at (existence checked)
 *   auto      server generated on create (e.g. policyNumber); rejected in request bodies
 *   default   applied on create when omitted
 *   example   used in the OpenAPI examples
 */

const str = (example, extra = {}) => ({ type: 'string', example, ...extra });
const int = (example, extra = {}) => ({ type: 'integer', example, ...extra });
const num = (example, extra = {}) => ({ type: 'number', example, ...extra });
const bool = (example, extra = {}) => ({ type: 'boolean', example, ...extra });
const date = (example, extra = {}) => ({ type: 'date', example, ...extra });
const ref = (resource, example, extra = {}) => ({ type: 'integer', ref: resource, example, ...extra });

